contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: val to set, and a boolean decide whether to call Initialized before SetMinSum
    function run(uint _val, bool callInit) public {
        // If callInit is true we call Initialized() first, then SetMinSum should revert on P but succeed on M.
        // We want a property that holds on P for all inputs: SetMinSum succeeds only when not initialized.

        if (callInit) {
            c.Initialized();
        }

        // capture whether SetMinSum reverts by calling it inside a try/catch via external call
        bool didRevert;
        try c.SetMinSum(_val) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // On original contract P: if we called Initialized() before, SetMinSum must revert (didRevert==true).
        // Express that as an assertion: when callInit==true then didRevert==true.
        assert(!callInit || didRevert);
    }

    // Allow receiving ETH if needed by caller (not used here but harmless)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am) public payable {
        // require that the contract is still uninitialized and that caller has enough balance and unlock passed
        // We cannot directly check 'intitalized' so we rely on behavior: SetMinSum should be callable before Initialized.
        // Ensure this test uses the existing state: read current MinSum before calling Collect.
        uint before = c.MinSum();

        // Call Collect which in the original should not modify MinSum in the uninitialized scenario
        c.Collect(_am);

        // After the call, MinSum should remain the same as before
        uint after = c.MinSum();
        assert(after == before);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: caller sends no ether here (Collect doesn't require msg.value), use _am and ensure caller had at least that balance via prior deposits is not possible here — but we only need to observe MinSum immutability when not initialized
    function run(uint _am) public payable {
        // Precondition: contract must be uninitialized so SetMinSum in original can still be called; check via trying to call Initialized() state is false only accessible via behavior — we require true so caller doesn't constrain inputs
        // Read MinSum before call
        uint before = c.MinSum();
        // Call Collect as the test caller
        c.Collect(_am);
        // After calling Collect (which may succeed or revert), ensure MinSum unchanged when contract is still not initialized.
        // We cannot call any internal flag, but in original contract MinSum can only be modified before Initialized() is called. Therefore, if Initialized() hasn't been called, MinSum must remain equal to before.
        // To ensure we only assert the general rule (which original satisfies and mutant breaks), we assert MinSum == before.
        assert(c.MinSum() == before);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint collectAmount) public payable {
        require(true);
        // ensure this test contract has enough ether to send
        require(address(this).balance >= collectAmount);

        // Call Collect from this test contract (as msg.sender)
        // This may succeed or revert depending on C's state; we don't catch revert — if it reverts the transaction fails
        c.Collect(collectAmount);

        // After calling Collect while C is uninitialized, SetMinSum should still revert on original contract.
        // We observe this by attempting to call SetMinSum via a low-level call and asserting it still fails.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", uint256(1)));
        // In the original contract, when intitalized == false, SetMinSum should be allowed (nonReentrant_ then if(intitalized) revert() prevents only when initialized==true).
        // However the mutant flipped the guard making SetMinSum revert when not initialized. We assert that SetMinSum DOES NOT succeed here.
        // The general rule: when contract is uninitialized, SetMinSum remains callable after Collect; thus ok should be true on original and false on mutant.
        assert(ok == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint collectAmt, uint setVal) public payable {
        require(true);
        // perform Collect as the calling address
        c.Collect(collectAmt);
        // Try calling SetMinSum. We observe success by calling it and then reading MinSum.
        // State-changing call must be top-level statements.
        c.SetMinSum(setVal);
        uint observed = c.MinSum();
        assert(observed == setVal);
    }
    receive() external payable { }
}

