contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor address and amounts for put and collect, and lockTime
    function testFuzz_property(address actor, uint256 putAmt, uint256 collectAmt, uint256 lockDelta) public {
        // keep amounts in reasonable ranges but wide
        vm.assume(actor != address(0));
        putAmt = bound(putAmt, 0, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);
        lockDelta = bound(lockDelta, 0, 1000000);

        // initial MinSum reading
        uint256 beforeMin = c.MinSum();

        // actor funds and performs Put with some lock
        vm.deal(actor, putAmt);
        vm.prank(actor);
        if (putAmt > 0) {
            // call Put with value
            c.Put{value: putAmt}(lockDelta);
