            c.Put(0);
        }

        // warp time to after unlock to allow Collect to proceed in cases where conditions met
        vm.warp(block.timestamp + lockDelta + 1);

        // try calling Collect as actor; capture whether it reverts or not
        vm.prank(actor);
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect, MinSum must be unchanged in the reference implementation for ANY input
