contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: depositor sends funds, sets MinSum and Log, initializes, then attempts a Collect;
    // we model a benign attacker by using this contract as msg.sender when interacting with c so we can reenter if protection is missing.
    receive() external payable {}

    // variables:
    // initMin - value to set as MinSum
    // depositAmt - amount we will put into c
    // collectAmt - amount we will ask to collect (<= depositAmt)
    // logAddr - address of an existing Log contract in the environment
    function run(uint initMin, uint depositAmt, uint collectAmt, address payable logAddr) public payable {
        require(msg.value == depositAmt, "send depositAmt as msg.value");
        // preconditions for meaningful execution
        require(depositAmt >= collectAmt, "deposit >= collect");

        // set MinSum and LogFile before initialized flag is set
        c.SetLogFile(logAddr);
        c.SetMinSum(initMin);
        c.Initialized();

        // Put funds into c from this contract (fallback of C will call Put if needed; we call Put directly)
        c.Put{value: depositAmt}(0);

        // read stored balance before collect
        uint before = c.Acc(address(this)).balance;

        // perform Collect: under original contract P this is non-reentrant and will deduct exactly collectAmt
        // under mutant M the lock clear is missing and a reentrant fallback in this contract could reenter and cause additional behavior.
        c.Collect{value:0}(collectAmt);

        // read stored balance after collect
        uint after = c.Acc(address(this)).balance;

        // Rule: after == before - collectAmt (i.e., the holder's stored balance is reduced exactly by the withdrawn amount)
        assert(after == before - collectAmt);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will trigger Collect which in the mutant allows reentrant calls from a fallback.
    // The test's receive reenters to call c.SetMinSum to try to change MinSum during Collect.
    // If the original nonReentrant_ correctly sets/clears the lock, the reentrant SetMinSum will revert and MinSum stays unchanged.

    // calldata: caller provides amounts and values to set up state externally (must be funded by caller)
    function run(address depositor, uint depositAmount, uint withdrawAmount, uint newMin) public payable {
        require(depositor != address(0));
        // Precondition: this test contract must hold enough ETH to fund the deposit and potential reentrant calls
        require(address(this).balance >= depositAmount, "need funds");
        // Setup: have depositor deposit by forwarding call through this contract's fallback to c.Put via low-level call is not allowed;
        // instead we simulate by calling Put from this test contract as if depositor is this contract.
        // So the depositor param is only informational; we act as depositor (this contract) for interactions.

        // Initialize MinSum to a known value that is less than or equal to current balance so Collect can proceed.
        // Set MinSum to 0 first (only callable before Initialized); keep intitalized false in original contract so allowed.
        // Call SetMinSum to 0
        c.SetMinSum(0);
        // Put funds into the contract as this contract (acts as depositor)
        c.Put{value: depositAmount}(0);
        // Ensure there is enough balance in c for withdrawAmount
        // Now set MinSum to something small so Collect condition passes
        c.SetMinSum(1);
        uint beforeMin = c.MinSum();
        // Prepare reentrant attempt: our receive() will be invoked if c sends ETH to this contract during Collect.
        // We store newMin in a storage spot by copying to a state var used by receive via calldata decoding is not allowed,
        // so we rely on the constructor parameter newMin being stored in a state var. Instead, use a storage slot.
        _targetNewMin = newMin;

        // Now call Collect to withdraw; during the external call, mutant may allow reentrancy and our receive will call SetMinSum
        c.Collect(withdrawAmount);
        // After Collect returns, MinSum must remain equal to beforeMin in the original; in mutant reentrancy it may have changed.
        uint afterMin = c.MinSum();
        assert(afterMin == beforeMin);
    }

    uint private _targetNewMin;

    receive() external payable {
        // During reentrant callback, attempt to change MinSum. This should revert under the original contract due to full nonReentrant_.
        // We ignore success/failure; we just try to invoke SetMinSum which in the mutant may succeed and mutate MinSum.
        // Call without checking for revert so that Collect's external call will observe behavior.
        // Use try/catch to avoid bubbling a revert to the outer call (but try/catch is not allowed for external call here per constraints?),
        // Instead call directly; if it reverts, the outer call flow will handle it as per original contract's behavior.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", _targetNewMin));
        ok; // suppress compiler warning about unused
    }
}

