contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // we need parameters: initial deposit amount, withdraw amount, and lockTime
    // The test will: deposit via fallback to ensure Acc[msg.sender].balance increases,
    // then call Collect to withdraw; if reentrancy allows unexpected extra deduction,
    // stored balance may fall by more than withdraw amount. We observe balances via public getter Acc.

    function run(uint depositAmount, uint withdrawAmount, uint lockTime) public payable {
        require(depositAmount >= withdrawAmount && address(this).balance >= depositAmount, true);

        // deposit into c by calling fallback which calls Put(0)
        // use low-level call to fallback so Put(0) is invoked (fallback forwards msg.value)
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // read stored balance before withdraw via public Acc getter: Acc returns Holder struct fields via autogenerated getter
        // Acc(address) returns (uint unlockTime, uint balance)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // call Collect with withdrawAmount
        c.Collect(withdrawAmount);

        // read stored balance after
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // Assert: the decrease in stored balance is at most withdrawAmount
        // i.e., beforeBalance - afterBalance <= withdrawAmount  (avoid underflow by using subtraction via comparisons)
        assert(!(afterBalance + withdrawAmount < beforeBalance));
    }

    receive() external payable { /* allow receiving ETH when Collect sends funds */ }
}

