pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // fuzz params: deposit amount and withdraw amount
    function testFuzz_property(uint256 deposit, uint256 withdraw) public {
        // keep amounts in reasonable ranges and non-zero
        deposit = bound(deposit, 1, 1 ether);
        withdraw = bound(withdraw, 1, 1 ether);

        // deploy attacker helper that will reenter Collect during the external call
        attacker = new Attacker(address(c));

        // initialize contract: set MinSum to some nonzero so attacker can try to change it
        vm.prank(address(this));
        c.SetMinSum(1);
        // set log file to attacker so Put/Collect log calls go to attacker (attacker implements fallback to reenter)
        vm.prank(address(this));
        c.SetLogFile(address(attacker));
        vm.prank(address(this));
        c.Initialized();

        // fund attacker externally so it can receive refunds and reenter
        vm.deal(address(attacker), 0);

        // give depositor funds
        address depositor = address(0xABCD);
        vm.deal(depositor, deposit);

        // depositor calls Put to set up balance and unlockTime in Acc
        vm.prank(depositor);
        c.Put(0{value: deposit}());

        // Sanity: ensure MinSum is what we set
        uint256 beforeMin = c.MinSum();

        // Now set attacker as the msg.sender for Collect by having attacker hold the funds
        // Transfer the depositor's balance to attacker by having depositor call Put with attacker (simulate attacker owning the account)
        // Instead, we will have attacker deposit itself so it has balance >= MinSum and can call Collect
        vm.deal(address(attacker), deposit);
        vm.prank(address(attacker));
        c.Put(0{value: deposit}());

        // Attacker will attempt to Collect(withdraw). During the external call to msg.sender.call in Collect,
        // the attacker fallback/receive will perform a reentrant call that tries to change MinSum via SetMinSum.
        // For the reference contract this should be prevented; for the mutant it can succeed and change MinSum.

        // Record MinSum before collect
        uint256 minBefore = c.MinSum();

        // Have attacker attempt Collect. Use try/catch to allow both revert and success.
        bool ok;
        try c.Collect(withdraw) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, assert that MinSum is unchanged (the general invariant for the correct contract)
        assertTrue(c.MinSum() == minBefore);
    }
}

// Minimal adversarial helper which on receiving funds will reenter C.Collect and call SetMinSum to change state.
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _t) {
        target = _t;
        reentered = false;
    }

    // Implement AddMessage signature so LogFile.AddMessage calls succeed
    function AddMessage(address, uint, string memory) public {
        // no-op
    }

    // receive will be invoked when Collect does msg.sender.call{value: _am}("")
    // Reenter and attempt to call SetMinSum to change MinSum. Only do once to avoid infinite recursion.
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // try to change MinSum; this should be prevented by proper reentrancy guard
            // call SetMinSum via low-level call to avoid needing to be the contract owner etc.
            // We directly call the function on C since it's public
            C(target).SetMinSum(999);
        }
    }
}

