pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // fuzz parameters: deposit to put into the victim, withdraw amount to trigger call, and newMin to try to set via reentrancy
    function testFuzz_property(uint256 deposit, uint256 withdraw, uint256 newMin) public {
        // keep values in reasonable ranges but still wide
        deposit = bound(deposit, 1, 1 ether);
        withdraw = bound(withdraw, 1, deposit);
        newMin = bound(newMin, 0, 2 ether);

        // deploy attacker that will re-enter Collect to call SetMinSum during the external call
        attacker = new Attacker(c);

        // Fund attacker and a victim EOA
        address victim = address(0xCAFE);
        vm.deal(victim, 2 ether);
        vm.deal(address(attacker), 2 ether);

        // Set up c: set MinSum to a value that attacker will try to change
        vm.prank(victim);
        c.SetMinSum(0); // allowed once before Initialized

        // Set the LogFile so Put/Collect will call external contract (attacker) via LogFile.AddMessage
        // The contract expects an address to be set via SetLogFile; pass attacker so its code runs during Put/Collect
        vm.prank(victim);
        c.SetLogFile(address(attacker));

        // mark initialized so SetMinSum cannot be called legitimately afterwards in normal flow
        vm.prank(victim);
        c.Initialized();

        // Have victim put funds into their account
        vm.prank(victim);
        c.Put{value: deposit}(0);

        // Attacker will be set up to, when Log.AddMessage is invoked, re-enter Collect and call SetMinSum(newMin)
        attacker.configureReentry(victim, withdraw, newMin);

        // Now perform Collect from victim: this will call LogFile.AddMessage which is attacker and will trigger reentry
        bool ok;
        vm.prank(victim);
        try c.Collect{value: 0}(withdraw) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL ASSERTION: In the reference contract, nonReentrant_ prevents reentrant changes to MinSum during Collect,
        // so regardless of inputs, MinSum remains the value set before (0). The mutant that removed the lock set/clear
        // can allow the attacker to change MinSum during Collect, so this assertion will fail on the mutant for some inputs.
        assertTrue(c.MinSum() == 0);
    }
}

// Minimal adversarial helper that acts as Log and during AddMessage will re-enter Collect and call SetMinSum
contract Attacker {
    C public victim;
    address public target; // the victim account to re-enter as
    uint256 public reenterWithdraw;
    uint256 public newMin;
    bool public reentered;

    constructor(C _v) {
        victim = _v;
    }

    // configure what the attacker should do when called as Log.AddMessage
    function configureReentry(address _target, uint256 _withdraw, uint256 _newMin) external {
        target = _target;
        reenterWithdraw = _withdraw;
        newMin = _newMin;
        reentered = false;
    }

    // This mimics Log.AddMessage signature; when called by victim contract during Put/Collect, trigger reentrancy
    function AddMessage(address /*_adr*/, uint /*_val*/, string memory /*_data*/) public {
        // Only attempt once to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // re-enter victim contract as the victim address
            // call Collect to cause code paths that may call SetMinSum in the mutant (or attacker can call SetMinSum directly)
            // First try to re-enter Collect
            // Use low-level call via the victim address to act as that EOA
